desired = {"name": "fab-db", "replicas": 3, "version": "16.4"}
actual = {"pods": ["fab-db-0"], "version": "16.3"}


def reconcile(spec, state):
    actions = []
    have = len(state["pods"])
    if have < spec["replicas"]:
        for i in range(have, spec["replicas"]):
            state["pods"].append(f"{spec['name']}-{i}")
            actions.append(f"create pod {spec['name']}-{i}")
    elif have > spec["replicas"]:
        while len(state["pods"]) > spec["replicas"]:
            actions.append(f"delete pod {state['pods'].pop()}")
    if state["version"] != spec["version"]:
        # 한 번에 하나씩 올린다(롤링) — 실제 운영 지식이 들어가는 자리
        actions.append(f"rolling upgrade {state['version']} -> {spec['version']} (one pod at a time)")
        state["version"] = spec["version"]
    return actions


print("1st:", reconcile(desired, actual))
print("2nd:", reconcile(desired, actual))  # 같은 입력이면 할 일이 없다(멱등)
desired["replicas"] = 2
print("3rd:", reconcile(desired, actual))

# 1st: ['create pod fab-db-1', 'create pod fab-db-2', 'rolling upgrade 16.3 -> 16.4 (one pod at a time)']
# 2nd: []
# 3rd: ['delete pod fab-db-2']
